import{_ as s,c as t,o as i,ag as o}from"./chunks/framework.BtwP-r-R.js";const n="/14B-POO-A26/assets/scenarios_tests_1.BEA74ez9.png",f=JSON.parse('{"title":"Les scénarios de tests","description":"","frontmatter":{},"headers":[],"relativePath":"tests_fonctionnels.md","filePath":"tests_fonctionnels.md"}'),r={name:"tests_fonctionnels.md"};function l(a,e,u,c,d,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="les-scenarios-de-tests" tabindex="-1">Les scénarios de tests <a class="header-anchor" href="#les-scenarios-de-tests" aria-label="Permalink to &quot;Les scénarios de tests&quot;">​</a></h1><h2 id="qu-est-ce-qu-un-scenario-de-test" tabindex="-1">Qu&#39;est-ce qu&#39;un scénario de test <a class="header-anchor" href="#qu-est-ce-qu-un-scenario-de-test" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;un scénario de test&quot;">​</a></h2><p>Un scénario de test est un scénario mesurant une fonctionnalité à travers un ensemble d&#39;actions ou de conditions (cas de test) pour vérifier le résultat attendu.</p><p>Les scénarios de tests s&#39;appliquent à n&#39;importe quelle application logicielle. Ils peuvent être faits manuellement ou de manière automatisée à travers des outils.</p><h2 id="qu-est-ce-qu-un-cas-de-test" tabindex="-1">Qu&#39;est-ce qu&#39;un cas de test <a class="header-anchor" href="#qu-est-ce-qu-un-cas-de-test" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;un cas de test&quot;">​</a></h2><p>Un cas de test est un ensemble d&#39;actions exécutées pour vérifier une caractéristique ou une fonctionnalité particulière de votre application logicielle.</p><p>Un cas de test contient :</p><ul><li>des étapes,</li><li>des données de test,</li><li>une précondition</li><li>une postcondition</li></ul><p>développés pour un scénario de test spécifique afin de vérifier toute exigence.</p><p>Le cas de test comprend des variables ou des conditions spécifiques, à l&#39;aide desquelles un testeur peut comparer les résultats attendus et réels pour déterminer si un produit logiciel fonctionne conformément aux exigences du client.</p><p>Exemple de Scénario de test :</p><ol><li>Vérifier la fonctionnalité de recherche.</li><li>Vérifier la fonctionnalité de paiement.</li><li>Vérifier la fonctionnalité de connexion (authentification).</li></ol><h2 id="pourquoi-ecrivons-nous-un-scenario-de-test" tabindex="-1">Pourquoi écrivons-nous un scénario de test ? <a class="header-anchor" href="#pourquoi-ecrivons-nous-un-scenario-de-test" aria-label="Permalink to &quot;Pourquoi écrivons-nous un scénario de test ?&quot;">​</a></h2><p>Voici des raisons importantes pour créer des scénarios de test :</p><ul><li>La principale raison d&#39;écrire des scénarios de tests est de vérifier la fonctionnalité complète de l&#39;application.</li><li>Ils vous aident également à vous assurer que les processus sont conformes aux exigences fonctionnelles.</li><li>Les scénarios de test peuvent être approuvés par diverses parties prenantes telles que : <ul><li>les analystes,</li><li>les développeurs</li><li>les clients pour s&#39;assurer que l&#39;application sous test est soigneusement testée. Ils garantissent que le logiciel fonctionne pour les cas d&#39;utilisation les plus courants.</li></ul></li><li>Ils servent d&#39;outil rapide pour déterminer l&#39;effort de travail de test et créer en conséquence une proposition pour le client pour organiser la main-d&#39;œuvre.</li><li>Ils aident à déterminer les transactions de bout en bout les plus critiques.</li><li>Une fois ces scénarios de test finalisés, les cas de test peuvent être facilement dérivés des scénarios de test.</li></ul><p>Exemple de cas de test</p><p><img src="'+n+'" alt="Formulaire de connexion"></p><p>Voici les différents cas de test pour le scénario &quot;Vérifier la fonctionnalité de connexion&quot; :</p><ol><li>Vérifiez le comportement du système lorsqu&#39;un courriel et un mot de passe valides sont entrés.</li><li>Vérifiez le comportement du système lorsqu&#39;un courriel invalide et un mot de passe valide sont saisis.</li><li>Vérifiez le comportement du système lorsqu&#39;un courriel valide et un mot de passe invalide sont saisis.</li><li>Vérifiez le comportement du système lorsqu&#39;un courriel invalide et un mot de passe invalide sont saisis.</li><li>Vérifiez le comportement du système lorsque le courriel et le mot de passe sont laissés vides et que le bouton « Se connecter » est cliqué.</li><li>Vérifiez que votre mot de passe oublié fonctionne comme prévu</li><li>Vérifiez le comportement du système lorsque « Se souvenir de moi » est coché</li></ol><p>Voici un exemple : <a href="https://gitlab.com/420-14b-fx/contenu/-/blob/main/bloc2/cours%2019/Exemple%20cas%20de%20test.pdf?ref_type=heads" target="_blank" rel="noreferrer">Exemple de cas de test</a></p><h2 id="pourquoi-ecrire-des-cas-de-test" tabindex="-1">Pourquoi écrire des cas de test <a class="header-anchor" href="#pourquoi-ecrire-des-cas-de-test" aria-label="Permalink to &quot;Pourquoi écrire des cas de test&quot;">​</a></h2><p>Voici quelques raisons importantes pour créer un cas de test</p><ul><li>Les cas de test aident à vérifier la conformité aux normes, directives et exigences des clients.</li><li>Vous aide à valider les attentes et les exigences des clients.</li><li>Couverture accrue du contrôle, de la logique et du flux de données.</li><li>Vous pouvez simuler des scénarios d&#39;utilisateur final &quot;réels&quot;.</li><li>Expose des erreurs ou des comportements non souhaités.</li><li>Lorsque les cas de test sont écrits pour l&#39;exécution des tests, le travail du testeur sera mieux organisé et simplifié</li></ul><h2 id="comment-bien-concevoir-un-cas-de-test" tabindex="-1">Comment bien concevoir un cas de test <a class="header-anchor" href="#comment-bien-concevoir-un-cas-de-test" aria-label="Permalink to &quot;Comment bien concevoir un cas de test&quot;">​</a></h2><ul><li>Les cas de test doivent être transparents et simples.</li><li>Créez un cas de test en gardant l&#39;utilisateur final à l&#39;esprit.</li><li>Vous devez vous assurer que vous rédigerez des cas de test pour vérifier toutes les exigences logicielles mentionnées dans le document de spécification.</li><li>Ne présumez jamais des fonctionnalités et des caractéristiques de votre application logicielle lors de la préparation d&#39;un cas de test.</li><li>Les cas de test doivent être facilement identifiables.</li></ul><h2 id="modele" tabindex="-1">Modèle <a class="header-anchor" href="#modele" aria-label="Permalink to &quot;Modèle&quot;">​</a></h2><p>Voici un modèle pour rédiger vos cas de tests : <a href="https://gitlab.com/420-14b-fx/contenu/-/blob/main/bloc2/cours%2019/CasTestModele.docx?ref_type=heads" target="_blank" rel="noreferrer">Modèle de cas de test</a></p>',27)])])}const q=s(r,[["render",l]]);export{f as __pageData,q as default};
